import{_ as t,c as i,o as a,ae as r}from"./chunks/framework.DMK_uHmU.js";const g=JSON.parse('{"title":"User List Management Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/Manage/Users/user-management.md","filePath":"Administration/Manage/Users/user-management.md"}'),s={name:"Administration/Manage/Users/user-management.md"};function n(l,e,o,c,u,d){return a(),i("div",null,e[0]||(e[0]=[r('<h1 id="user-list-management-guide" tabindex="-1">User List Management Guide <a class="header-anchor" href="#user-list-management-guide" aria-label="Permalink to &quot;User List Management Guide&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The User List component provides a comprehensive interface for managing user accounts within the system. It allows administrators to view, search, filter, and access individual user profiles for detailed management.</p><h2 id="accessing-the-user-list" tabindex="-1">Accessing the User List <a class="header-anchor" href="#accessing-the-user-list" aria-label="Permalink to &quot;Accessing the User List&quot;">​</a></h2><p>The User List component is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>To access this component, navigate to <code>/users/UserList</code> in the system. You&#39;ll typically find a link to this page in the administration menu or user management section.</p><h2 id="user-list-interface-overview" tabindex="-1">User List Interface Overview <a class="header-anchor" href="#user-list-interface-overview" aria-label="Permalink to &quot;User List Interface Overview&quot;">​</a></h2><p>The User List interface consists of these key components:</p><ol><li><strong>Header Section</strong>: Contains the title &quot;User Management&quot; with user count badge, description, and action buttons</li><li><strong>Search and Filter Controls</strong>: Search box and filter buttons to find specific users</li><li><strong>Data Table</strong>: Displays user information in a scrollable, sortable table</li><li><strong>Action Buttons</strong>: <ul><li>Add new user</li><li>Refresh data</li><li>Clear filters</li><li>Export to Excel</li></ul></li></ol><h2 id="navigating-the-user-list" tabindex="-1">Navigating the User List <a class="header-anchor" href="#navigating-the-user-list" aria-label="Permalink to &quot;Navigating the User List&quot;">​</a></h2><h3 id="sorting-users" tabindex="-1">Sorting Users <a class="header-anchor" href="#sorting-users" aria-label="Permalink to &quot;Sorting Users&quot;">​</a></h3><p>To sort the user list:</p><ol><li>Click on any column header to sort by that field</li><li>Click again to toggle between ascending and descending order</li><li>Click a third time to remove sorting</li></ol><p>Default sort is by &quot;Updated&quot; field in descending order (most recent first).</p><h3 id="filtering-users" tabindex="-1">Filtering Users <a class="header-anchor" href="#filtering-users" aria-label="Permalink to &quot;Filtering Users&quot;">​</a></h3><p>There are multiple ways to filter the user list:</p><ol><li><p><strong>Global Search</strong>:</p><ul><li>Enter text in the search box in the top-right corner</li><li>The system will search across display name, first name, last name, username, and organization fields</li></ul></li><li><p><strong>Column Filters</strong>:</p><ul><li>Each column has a filter menu accessible by clicking the filter icon in the column header</li><li>Organization field: Select from a dropdown of available organizations</li><li>Access Level field: Select from User, Manager, Content, or Admin</li><li>Updated field: Select a date with the calendar picker</li></ul></li><li><p><strong>Filter Indicator</strong>:</p><ul><li>When filters are active, the filter button turns blue</li><li>Click the &quot;Filter Slash&quot; button to clear all active filters</li></ul></li></ol><h3 id="quick-filter-buttons" tabindex="-1">Quick Filter Buttons <a class="header-anchor" href="#quick-filter-buttons" aria-label="Permalink to &quot;Quick Filter Buttons&quot;">​</a></h3><p>The interface provides quick filter buttons for common filtering needs:</p><ol><li><strong>Admins</strong>: Shows only users with Admin access level</li><li><strong>Creators</strong>: Shows only users with Content access level</li><li><strong>Recent</strong>: Sorts users by most recently updated</li><li><strong>Deleted</strong>: Refreshes the list (may include deleted users if enabled)</li></ol><h2 id="user-management-actions" tabindex="-1">User Management Actions <a class="header-anchor" href="#user-management-actions" aria-label="Permalink to &quot;User Management Actions&quot;">​</a></h2><h3 id="creating-a-new-user" tabindex="-1">Creating a New User <a class="header-anchor" href="#creating-a-new-user" aria-label="Permalink to &quot;Creating a New User&quot;">​</a></h3><p>To create a new user:</p><ol><li>Click the &quot;+ User&quot; button in the top-right corner</li><li>You&#39;ll be redirected to the user profile page with empty fields</li><li>Complete the required information</li><li>Click &quot;Submit&quot; to create the user</li></ol><h3 id="viewing-and-editing-user-profiles" tabindex="-1">Viewing and Editing User Profiles <a class="header-anchor" href="#viewing-and-editing-user-profiles" aria-label="Permalink to &quot;Viewing and Editing User Profiles&quot;">​</a></h3><p>To view or edit a user&#39;s profile:</p><ol><li>Click on any row in the table</li><li>You&#39;ll be redirected to that user&#39;s profile page</li><li>Make necessary changes</li><li>Click &quot;Submit&quot; to save changes</li></ol><h3 id="exporting-user-data" tabindex="-1">Exporting User Data <a class="header-anchor" href="#exporting-user-data" aria-label="Permalink to &quot;Exporting User Data&quot;">​</a></h3><p>To export the user list to Excel:</p><ol><li>Click the &quot;Export&quot; button (external link icon)</li><li>Confirm the export in the dialog that appears</li><li>The browser will download a CSV file</li><li>The export includes all currently visible users (respects active filters)</li></ol><h2 id="understanding-user-information" tabindex="-1">Understanding User Information <a class="header-anchor" href="#understanding-user-information" aria-label="Permalink to &quot;Understanding User Information&quot;">​</a></h2><p>The user list displays the following information for each user:</p><ol><li><strong>Avatar</strong>: Displays user initials in a circular badge</li><li><strong>First Name</strong>: User&#39;s first name</li><li><strong>Last Name</strong>: User&#39;s last name</li><li><strong>Username</strong>: Unique system identifier (with disabled badge if applicable)</li><li><strong>Organization</strong>: Primary organizational unit(s)</li><li><strong>Access Level</strong>: User permission level with color-coded indicator</li><li><strong>Updated</strong>: Date when the user profile was last modified</li></ol><h3 id="user-status-indicators" tabindex="-1">User Status Indicators <a class="header-anchor" href="#user-status-indicators" aria-label="Permalink to &quot;User Status Indicators&quot;">​</a></h3><p>Special indicators help identify user status:</p><ul><li><strong>Disabled Badge</strong>: Red &quot;Disabled&quot; badge appears next to username for inactive accounts</li></ul><h3 id="access-level-indicators" tabindex="-1">Access Level Indicators <a class="header-anchor" href="#access-level-indicators" aria-label="Permalink to &quot;Access Level Indicators&quot;">​</a></h3><p>Access levels are displayed with color-coded chips:</p><ul><li><strong>User</strong>: Gray</li><li><strong>Manager</strong>: Purple</li><li><strong>Content</strong>: Green</li><li><strong>Admin</strong>: Blue</li></ul><p>Each chip shows the first letter of the access level and the full name.</p><h2 id="advanced-features" tabindex="-1">Advanced Features <a class="header-anchor" href="#advanced-features" aria-label="Permalink to &quot;Advanced Features&quot;">​</a></h2><h3 id="state-persistence" tabindex="-1">State Persistence <a class="header-anchor" href="#state-persistence" aria-label="Permalink to &quot;State Persistence&quot;">​</a></h3><p>The User List component saves your view preferences:</p><ul><li>Column order</li><li>Sort order</li><li>Visible columns</li><li>Scroll position</li></ul><p>These preferences are stored in the session, so they persist when you navigate away and return.</p><h3 id="column-customization" tabindex="-1">Column Customization <a class="header-anchor" href="#column-customization" aria-label="Permalink to &quot;Column Customization&quot;">​</a></h3><p>You can customize the table view:</p><ol><li><strong>Reorder Columns</strong>: Drag and drop column headers to change their order</li><li><strong>Resize Columns</strong>: Drag the edge between column headers</li><li><strong>Responsive Display</strong>: On smaller screens, less important columns automatically hide</li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: User list is empty</p><ul><li>Check if filters are active (blue filter button indicates active filters)</li><li>Click the &quot;Clear Filters&quot; button to remove all filters</li><li>Refresh the data using the refresh button</li><li>Check for network connectivity issues</li></ul><p><strong>Issue</strong>: Unable to sort or filter</p><ul><li>Ensure you have proper permissions (Admin, Content, or Manager roles)</li><li>Try refreshing the browser page</li><li>Check browser console for JavaScript errors</li></ul><p><strong>Issue</strong>: Export not working</p><ul><li>Check browser download settings</li><li>Ensure you have proper permissions</li><li>Try with a smaller dataset by applying filters first</li></ul><p><strong>Issue</strong>: Cannot find a specific user</p><ul><li>Use the global search to search by name, username, or organization</li><li>Try searching with partial information</li><li>Check if the user account may be disabled</li><li>Verify the user exists in the system</li></ul><p><strong>Issue</strong>: Changes to user not appearing</p><ul><li>Click the refresh button to reload the latest data</li><li>Check if another administrator made conflicting changes</li><li>Verify the changes were saved successfully</li></ul><hr><p>For additional assistance with user list management, please contact your system administrator.</p>',62)]))}const m=t(s,[["render",n]]);export{g as __pageData,m as default};
